if (! function_exists('uf_item')) {
    /**
     * @param  list<string>  $match_terms
     * @param  array<string, string>  $specs
     * @param  array<string, mixed>  $extra
     * @return array<string, mixed>
     */
    function uf_item(
        int $list_id,
        string $sku,
        string $name,
        string $brand,
        string $category_path,
        int $street_price,
        string $availability,
        string $image_key,
        string $family,
        array $match_terms,
        string $short_description,
        array $specs,
        bool $featured = false,
        array $extra = [],
    ): array {
        $item = [
            'list_id' => $list_id,
            'sku' => $sku,
            'name' => $name,
            'brand' => $brand,
            'category_path' => $category_path,
            'street_price' => $street_price,
            'availability' => $availability,
            'image_key' => $image_key,
            'family' => $family,
            'match_terms' => $match_terms,
            'match_skus' => array_values(array_unique(array_merge([$sku], $extra['match_skus'] ?? []))),
            'featured' => $featured,
            'short_description' => $short_description,
            'specs' => $specs,
        ];

        foreach (['suitable_for', 'advantages', 'faqs', 'mpn', 'warranty_months', 'google_product_category', 'recommendations'] as $key) {
            if (array_key_exists($key, $extra)) {
                $item[$key] = $extra[$key];
            }
        }

        return $item;
    }
}

